// The clinic's schedule, and everything the page derives from "now".
//
// One authored value drives the whole route: `nowMin`, minutes since midnight
// on the current local day. The status statement, the countdown, the sweep line
// on the week strip, the accent colour, and the walk-in chips on the six
// services all read from the single object returned by readClock().

export const HOURS = [
  { day: 'Monday', short: 'Mon', open: '8:00', close: '20:00' },
  { day: 'Tuesday', short: 'Tue', open: '8:00', close: '20:00' },
  { day: 'Wednesday', short: 'Wed', open: '8:00', close: '20:00' },
  { day: 'Thursday', short: 'Thu', open: '8:00', close: '20:00' },
  { day: 'Friday', short: 'Fri', open: '8:00', close: '17:00' },
  { day: 'Saturday', short: 'Sat', open: '9:00', close: '14:00' },
  { day: 'Sunday', short: 'Sun', open: null, close: null },
]

// Registration closes this many minutes before the doors do.
export const REGISTRATION_LEAD = 30

// The axis every bar on the week strip is measured against.
export const AXIS_START = 6 * 60
export const AXIS_END = 21 * 60

// HOURS is indexed Monday-first; Date#getDay() is Sunday-first.
const DAY_INDEX = [6, 0, 1, 2, 3, 4, 5]

export function toMinutes(hhmm) {
  const [h, m] = hhmm.split(':').map(Number)
  return h * 60 + m
}

export function formatClock(min) {
  const h = Math.floor(min / 60)
  const m = min % 60
  return `${h}:${String(m).padStart(2, '0')}`
}

export function formatDuration(min) {
  if (min <= 0) return '0 min'
  const h = Math.floor(min / 60)
  const m = min % 60
  if (h === 0) return `${m} min`
  if (m === 0) return `${h} hr`
  return `${h} hr ${m} min`
}

export function axisPercent(min) {
  return ((min - AXIS_START) / (AXIS_END - AXIS_START)) * 100
}

/**
 * Everything the page needs to know about this moment.
 * status: 'open' | 'last-call' | 'registration-closed' | 'closed'
 */
export function readClock(date = new Date()) {
  const nowMin = date.getHours() * 60 + date.getMinutes()
  const todayIndex = DAY_INDEX[date.getDay()]
  const today = HOURS[todayIndex]

  const base = {
    nowMin,
    todayIndex,
    today,
    openMin: null,
    closeMin: null,
    registrationCloseMin: null,
    minutesLeft: 0,
    status: 'closed',
    doorsOpen: false,
    nextDay: null,
    nextOpenMin: null,
  }

  if (today.open) {
    base.openMin = toMinutes(today.open)
    base.closeMin = toMinutes(today.close)
    base.registrationCloseMin = base.closeMin - REGISTRATION_LEAD
    base.doorsOpen = nowMin >= base.openMin && nowMin < base.closeMin

    if (base.doorsOpen) {
      base.minutesLeft = base.registrationCloseMin - nowMin
      if (nowMin >= base.registrationCloseMin) base.status = 'registration-closed'
      else if (base.minutesLeft <= 60) base.status = 'last-call'
      else base.status = 'open'
    }
  }

  if (base.status === 'closed' || base.status === 'registration-closed') {
    // Find the next day the doors open, starting with the rest of today.
    for (let step = base.status === 'closed' && !base.doorsOpen && today.open && nowMin < base.openMin ? 0 : 1; step <= 7; step++) {
      const d = HOURS[(base.todayIndex + step) % 7]
      if (!d.open) continue
      base.nextDay = step === 0 ? 'today' : step === 1 ? 'tomorrow' : d.day
      base.nextOpenMin = toMinutes(d.open)
      break
    }
  }

  return base
}

/**
 * Dev/inspection override so both the open and the closed composition can be
 * rendered and screenshotted on demand: ?now=1975-06-05T19:45
 */
export function clockDate() {
  if (typeof window === 'undefined') return new Date()
  const q = new URLSearchParams(window.location.search).get('now')
  if (!q) return new Date()
  const d = new Date(q)
  return Number.isNaN(d.getTime()) ? new Date() : d
}

import { useEffect, useRef, useState } from 'react'
import {
  HOURS,
  AXIS_START,
  AXIS_END,
  REGISTRATION_LEAD,
  axisPercent,
  formatClock,
  toMinutes,
} from './clock.js'

const TICKS = [
  { min: 6 * 60, label: '6am' },
  { min: 9 * 60, label: '9am' },
  { min: 12 * 60, label: 'noon' },
  { min: 15 * 60, label: '3pm' },
  { min: 18 * 60, label: '6pm' },
  { min: 21 * 60, label: '9pm' },
]

/**
 * The signature component: the clinic's week drawn on one shared time axis,
 * with the live moment swept across it.
 *
 * It answers the question the visitor actually arrived with — can I walk in,
 * and how long have I got — by putting "now" inside the schedule rather than
 * beside it. Every bar carries the last-30-minutes tail hatched out, because
 * registration closing before the doors do is the fact people get wrong.
 */
export default function WalkInClock({ clock, reducedMotion }) {
  const { nowMin, todayIndex, status, doorsOpen } = clock
  const nowPct = Math.min(100, Math.max(0, axisPercent(nowMin)))
  const inAxis = nowMin >= AXIS_START && nowMin <= AXIS_END

  // The sweep is drawn from the start of the axis to "now" once, on entry.
  // Reduced motion gets the resolved position with no travel.
  const gridRef = useRef(null)
  const [swept, setSwept] = useState(reducedMotion)
  useEffect(() => {
    if (reducedMotion) return setSwept(true)
    const el = gridRef.current
    if (!el) return
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) {
          if (e.isIntersecting) {
            requestAnimationFrame(() => setSwept(true))
            io.disconnect()
          }
        }
      },
      { rootMargin: '-8% 0px -35% 0px' },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [reducedMotion])

  return (
    <figure className={`clock clock--${status}`} aria-labelledby="clock-cap">
      <div className="clock__axis" aria-hidden="true">
        {TICKS.map((t) => (
          <span key={t.min} className="clock__tick" style={{ left: `${axisPercent(t.min)}%` }}>
            {t.label}
          </span>
        ))}
      </div>

      <div className="clock__grid" ref={gridRef}>
        {TICKS.map((t) => (
          <span
            key={t.min}
            className="clock__gridline"
            style={{ left: `${axisPercent(t.min)}%` }}
            aria-hidden="true"
          />
        ))}

        {inAxis && (
          <div
            className={`clock__sweep${swept ? ' is-swept' : ''}`}
            style={{ '--now': `${nowPct}%` }}
            aria-hidden="true"
          >
            <span className="clock__sweep-flag">{formatClock(nowMin)}</span>
          </div>
        )}

        <ol className="clock__days">
          {HOURS.map((d, i) => {
            const isToday = i === todayIndex
            const openMin = d.open ? toMinutes(d.open) : null
            const closeMin = d.close ? toMinutes(d.close) : null
            const regMin = closeMin === null ? null : closeMin - REGISTRATION_LEAD
            const left = openMin === null ? 0 : axisPercent(openMin)
            const width = openMin === null ? 0 : axisPercent(closeMin) - left
            const tailWidth =
              closeMin === null ? 0 : ((closeMin - regMin) / (closeMin - openMin)) * 100
            const elapsed =
              isToday && doorsOpen
                ? Math.min(100, ((nowMin - openMin) / (closeMin - openMin)) * 100)
                : 0

            return (
              <li
                key={d.day}
                className={`clock__day${isToday ? ' is-today' : ''}${d.open ? '' : ' is-shut'}`}
                data-day={d.day.toLowerCase()}
              >
                <span className="clock__label">
                  <b>{d.short}</b>
                  {isToday && <em className="clock__badge">today</em>}
                </span>

                <span className="clock__track">
                  {d.open ? (
                    <span className="clock__bar" style={{ left: `${left}%`, width: `${width}%` }}>
                      {isToday && doorsOpen && (
                        <span
                          className={`clock__elapsed${swept ? ' is-swept' : ''}`}
                          style={{ '--elapsed': `${elapsed}%` }}
                        />
                      )}
                      <span className="clock__tail" style={{ width: `${tailWidth}%` }} />
                      <span className="clock__hours">
                        {d.open}<span className="clock__dash">–</span>{d.close}
                      </span>
                    </span>
                  ) : (
                    <span className="clock__shut">Closed all day</span>
                  )}
                </span>
              </li>
            )
          })}
        </ol>
      </div>

      <figcaption id="clock-cap" className="clock__legend">
        <span className="clock__key clock__key--open">Doors open</span>
        <span className="clock__key clock__key--tail">
          Last {REGISTRATION_LEAD} min — no new walk-in registrations
        </span>
        <span className="clock__key clock__key--now">Now</span>
      </figcaption>
    </figure>
  )
}

