import { chromium } from 'playwright'
const base = 'http://localhost:4988/'
const b = await chromium.launch()
const errs = []
for (const spec of process.argv.slice(2)) {
  const [name, w, h, query, opts = ''] = spec.split('|')
  const ctx = await b.newContext({
    viewport: { width: +w, height: +h },
    deviceScaleFactor: 2,
    reducedMotion: opts.includes('reduced') ? 'reduce' : 'no-preference',
  })
  const p = await ctx.newPage()
  p.on('console', (m) => { if (m.type() === 'error') errs.push(`${name}: ${m.text()}`) })
  p.on('pageerror', (e) => errs.push(`${name}: ${e.message}`))
  await p.goto(base + (query || ''), { waitUntil: 'networkidle' })
  await p.waitForTimeout(500)
  // Walk the page so scroll-triggered entrances resolve the way a reader sees them.
  const H = await p.evaluate(() => document.body.scrollHeight)
  for (let y = 0; y < H; y += Math.round(+h * 0.6)) {
    await p.evaluate((v) => window.scrollTo(0, v), y)
    await p.waitForTimeout(190)
  }
  await p.waitForTimeout(700)
  const ow = await p.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth)
  if (ow > 0) errs.push(`${name}: horizontal overflow ${ow}px`)
  const stuck = await p.evaluate(() =>
    [...document.querySelectorAll('[data-reveal]')].filter((n) => !n.classList.contains('is-in')).length)
  if (stuck) errs.push(`${name}: ${stuck} region(s) never revealed`)
  if (opts.includes('view')) {
    const y = +(opts.match(/y(\d+)/)?.[1] ?? 0)
    await p.evaluate((v) => window.scrollTo(0, v), y)
    await p.waitForTimeout(800)
    await p.screenshot({ path: `.shots/${name}.png` })
  } else {
    await p.evaluate(() => window.scrollTo(0, 0))
    await p.waitForTimeout(400)
    await p.screenshot({ path: `.shots/${name}.png`, fullPage: true })
  }
  await ctx.close()
}
await b.close()
console.log(errs.length ? errs.join('\n') : 'clean: no console errors, no overflow, all regions revealed')
EOF
