const b = await chromium.launch()
const p = await (await b.newContext({ viewport: { width: 1440, height: 2400 } })).newPage()
await p.goto('http://localhost:4988/?now=2026-08-31T15:20', { waitUntil: 'networkidle' })
await p.evaluate(async () => { for (let y=0;y<document.body.scrollHeight;y+=600){window.scrollTo(0,y);await new Promise(r=>setTimeout(r,120))} window.scrollTo(0,0) })
await p.waitForTimeout(600)
const sel = 'a[href], button, input, select'
const n = await p.locator(sel).count()
for (let i = 0; i < n; i++) {
  const el = p.locator(sel).nth(i)
  const id = await el.evaluate((x) => x.tagName + '.' + (x.className || '') + ' "' + (x.textContent || '').trim().slice(0, 22) + '"')
  const snap = (x) => { const c = getComputedStyle(x); return [c.backgroundColor,c.color,c.borderColor,c.boxShadow,c.transform,c.textDecorationColor,c.opacity].join('|') }
  const before = await el.evaluate(snap)
  try { await el.hover({ timeout: 1500 }) } catch { console.log('UNHOVERABLE', id); continue }
  await p.waitForTimeout(250)
  const after = await el.evaluate(snap)
  await el.evaluate((x) => x.focus())
  await p.waitForTimeout(150)
  const foc = await el.evaluate((x) => getComputedStyle(x).outlineWidth + getComputedStyle(x).outlineStyle)
  if (before === after && foc.includes('none')) console.log('NO RESPONSE:', id, foc)
}
console.log('checked', n)
await b.close()
